function bearer(request) {
    const match = String(request.headers.get('authorization') || '').match(/^Bearer\s+([A-Za-z0-9_-]{20,200})$/);
    return match ? match[1] : '';
}
async function isPc(request, env) {
    const token = bearer(request);
    const pc = token ? await get(env, 'pc') : null;
    return Boolean(pc && pc.hash === await sha(token));
}
async function phoneOf(request, env) {
    const token = bearer(request);
    if (!token) return '';
    const hash = await sha(token);
    const devices = (await get(env, 'devices')) || [];
    return devices.some((device) => device.hash === hash) ? hash : '';
}
